        self.assertEqual(tan_from_note("Anforderung 4711 vom 24.01.2027, TAN: 318205"), "318205")

    def test_dates_and_times_are_not_tans(self):
        self.assertEqual(tan_from_note("Mail vom 24.01.2027 09:15: Code 552901"), "552901")
        self.assertIsNone(tan_from_note("Mail vom 24.01.2027 09:15, kein Code"))

    def test_no_note(self):
        self.assertIsNone(tan_from_note(""))


if __name__ == "__main__":
    unittest.main()

