# OWNER: (name)   ROLE: calculator (plain code, no model)   NEEDS: quantities, requirements, materials, discount,
#                 authority, verification   WRITES: results["bid"] (the answer object, see swarm.bidmath.answer)
"""Deterministic pricing, lead time and allocations per the brief's rules, on top of swarm.bidmath.

A position that cannot be priced is omitted (partial submission) and named in `notes`. A breakdown field whose
inputs were not found is left out of the entry (blank = unanswered) instead of being reported as a wrong 0.
"""
from swarm import Agent, Phase, register
from swarm.bidmath import (BASE_AND_SURCHARGE, BASE_ONLY, NO_DISCOUNT, ZERO, Band, Bid, D, PositionFacts, RateWindow,
                           Scale, allocate_cents, answer, base_unit_price_eur, carton_cost, final_pieces,
                           lead_time_weeks, marginal_credit, order_discount, plain, rate_on, undiscounted_net)
from swarm.facts import brief_facts, iso_date, number, scenario_date, token

CLAUSES = {"base_only": BASE_ONLY, "base_and_surcharge": BASE_AND_SURCHARGE, "none": NO_DISCOUNT}


@register
class BidCalculator(Agent):
    """Deterministic pricing/lead time/allocation per the brief's rules. Keep rounding rules in tested pure functions."""
    phase = Phase.COMPUTE

    async def run(self) -> None:
        board = self.ctx.board
        facts = await brief_facts(self.ctx)
        bid = compute(facts, board.get("quantities") or {}, board.get("requirements") or {},
                      board.get("materials") or {}, board.get("discount") or {}, board.get("authority") or {},
                      board.get("verification") or {})
        await board.set("bid", bid)
        self.log.info("bid: %s, %d positions, discount %s, total %s; %s", bid["decision"], len(bid["positions"]),
                      bid["discount_percent"], bid["total_net"], bid["notes"])


def _data(authority: dict, topic: str) -> dict:
    return (authority.get(topic) or {}).get("data") or {}


def _lookup(table: dict, key):
    """A keyed value whatever the key's spacing/case on the page ('VP-1134' == 'vp 1134')."""
    if not key or not isinstance(table, dict):
        return None
    return next((v for k, v in table.items() if token(k) == token(key)), None)


def condition_on(conditions: list[dict], material: str, on) -> dict | None:
    """Rule 4: the material's price condition valid on the scenario date, both endpoints inclusive."""
    valid = [c for c in conditions if token(c.get("material")) == token(material)
             and (iso_date(c.get("valid_from")) is None or on is None or iso_date(c["valid_from"]) <= on)
             and (iso_date(c.get("valid_to")) is None or on is None or on <= iso_date(c["valid_to"]))]
    return max(valid, key=lambda c: iso_date(c.get("valid_from")) or iso_date("1900-01-01")) if valid else None


def compute(facts, quantities, requirements, materials, discount, authority, verification) -> dict:
    reference = plain(facts.get("tender_reference"))
    on = scenario_date(facts)
    if verification.get("decision") == "no_bid":
        return answer(Bid(tender_reference=reference, decision="no_bid", notes="no active matching material"))

    positions = quantities.get("positions") or {}
    keys = quantities.get("keys") or {}
    by_req = requirements.get("by_position") or {}
    by_mat = materials.get("by_position") or {}
    catalog = materials.get("catalog") or {}
    conditions = materials.get("conditions") or []
    omit = set(verification.get("omit") or [])
    skipped: dict[str, str] = {}

    # pieces for every position with a material (pooled demand counts them all, rule 15)
    pieces: dict[str, int] = {}
    for pos, info in positions.items():
        try:
            pieces[pos] = final_pieces(info.get("quantity"), info.get("unit") or "",
                                       (by_req.get(pos) or {}).get("pieces_per_set"))
        except Exception as error:  # noqa: BLE001
            skipped[pos] = f"quantity: {error}"
    pooled: dict[str, int] = {}
    for pos, n in pieces.items():
        if by_mat.get(pos):
            pooled[by_mat[pos]] = pooled.get(by_mat[pos], 0) + n

    fx = _data(authority, "fx").get("rates") or {}
    metal = _data(authority, "metal_index").get("codes") or {}
    clauses = _data(authority, "clauses").get("groups") or {}
    tariffs = _data(authority, "packaging").get("tariffs") or {}
    commitments = _data(authority, "commitments").get("commitments") or {}
    pools = _data(authority, "setup_pool").get("pools") or {}
    bands = _data(authority, "bonus").get("bands") or []

    built: dict[str, PositionFacts] = {}
    unknown_fields: dict[str, set] = {}
    for pos in positions:
        material = by_mat.get(pos)
        if pos in omit or pos in skipped or not material:
            skipped.setdefault(pos, "omitted by verification" if pos in omit else "no material")
            continue
        m, n, k = catalog.get(material) or {}, pieces[pos], keys.get(pos) or {}
