            credit = marginal_credit(sum(eligible.values(), ZERO),
                                     [Band(number(b.get("lower_eur")) or 0, number(b.get("upper_eur")),
                                           number(b.get("percent")) or 0) for b in bands])
            for p, share in allocate_cents(credit, eligible).items():
                built[p].project_bonus = share
        else:
            for p in eligible:
                unknown_fields[p].add("rebate_total")

    # discount (rules 5, 16): the approved percentage, conditional on the undiscounted net of the bid
    net = undiscounted_net([(f.pieces, f.base_unit_price) for f in built.values()])
    percent = order_discount(number(discount.get("percent")) or 0, number(discount.get("threshold")), net, "bid")

    notes = "; ".join(f"{p} omitted: {why}" for p, why in sorted(skipped.items()))
    result = answer(Bid(tender_reference=reference, decision="bid", discount_percent=percent,
                        positions=[built[p] for p in sorted(built)], notes=notes[:3900]))
    for entry in result["positions"]:
        for field in unknown_fields.get(entry["position"], ()):
            entry.pop(field, None)        # blank = unanswered, better than a wrong 0
    return result

