  const out = [];
  const walk = (root, path) => {
    root.querySelectorAll('*').forEach(el => {
      const t = (el.tagName||'').toLowerCase();
      if (t === 'input' && ['range','checkbox'].includes(el.type)) out.push({path, tag: t, type: el.type, value: el.value, checked: el.checked, disabled: el.disabled, id: el.id, name: el.name, cls: el.className, aria: el.getAttribute('aria-label'), visible: !!(el.offsetWidth||el.offsetHeight), host: root.host ? root.host.tagName : null, label: (el.closest('label')||{}).innerText});
      if (el.shadowRoot) walk(el.shadowRoot, path + '>' + t);
    });
  };
  walk(document, 'doc');
  const locks = [...document.querySelectorAll('*')].filter(e => e.shadowRoot).map(e => ({tag: e.tagName, text: (e.shadowRoot.textContent||'').slice(0,200)}));
  return JSON.stringify({inputs: out, shadow_hosts: locks, gesperrt: document.body.innerText.includes('Gesperrt')});
}"""
