        for _ in range(4):
            if await pg.locator('input[type=password]').count():
                await pg.fill('input[name=username], input[type=text]', "$U"); await pg.fill('input[type=password]', "$P")
                await pg.click('button[type=submit], input[type=submit]'); await pg.wait_for_load_state("domcontentloaded")
            if "/consent" in pg.url:
                await pg.click('form[action*="consent"] button[type=submit], form[action*="consent"] input[type=submit]'); await pg.wait_for_load_state("domcontentloaded")
        await pg.wait_for_timeout(1500)
        print("URL", pg.url)
        print(json.dumps(json.loads(await pg.evaluate(JS)), indent=1, ensure_ascii=False)[:5000])
        html = await pg.evaluate("() => { const e=[...document.querySelectorAll('*')].find(x => x.shadowRoot); return e ? e.outerHTML.slice(0,300) + ' || SHADOW: ' + e.shadowRoot.innerHTML.slice(0,3000) : document.body.innerHTML.slice(0,3000) }")
        print(html)
        await b.close()
asyncio.run(main())
EOF
